using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using Microsoft.AspNetCore.Mvc;

namespace SecureVault.Controllers
{
    public class AccountBalance
    {
        public string AccountId { get; set; }
        public decimal Balance { get; set; }
        public long Version { get; set; }
        public DateTime LastModified { get; set; }
    }

    public interface ILedgerStore
    {
        AccountBalance GetBalance(string accountId);
        bool UpdateBalance(string accountId, decimal newBalance, long expectedVersion);
    }

    public class FileLedgerStore : ILedgerStore
    {
        private readonly string _dataDir;
        private readonly ReaderWriterLockSlim _rwLock = new ReaderWriterLockSlim();
        private readonly ConcurrentDictionary<string, AccountBalance> _cache = new();

        public FileLedgerStore(string dataDir)
        {
            _dataDir = Path.GetFullPath(dataDir);
            if (!Directory.Exists(_dataDir))
                Directory.CreateDirectory(_dataDir);
        }

        private string GetAccountPath(string accountId)
        {
            var sanitized = Convert.ToHexString(
                SHA256.HashData(Encoding.UTF8.GetBytes(accountId))).Substring(0, 16);
            var path = Path.GetFullPath(Path.Combine(_dataDir, sanitized + ".dat"));
            if (!path.StartsWith(_dataDir + Path.DirectorySeparatorChar))
                throw new InvalidOperationException("Path traversal detected");
            return path;
        }

        public AccountBalance GetBalance(string accountId)
        {
            _rwLock.EnterReadLock();
            try
            {
                if (_cache.TryGetValue(accountId, out var cached))
                    return new AccountBalance
                    {
                        AccountId = cached.AccountId,
                        Balance = cached.Balance,
                        Version = cached.Version,
                        LastModified = cached.LastModified
                    };

                var path = GetAccountPath(accountId);
                if (!File.Exists(path))
                    return null;

                var data = File.ReadAllText(path);
                var parts = data.Split('|');
                var balance = new AccountBalance
                {
                    AccountId = accountId,
                    Balance = decimal.Parse(parts[0]),
                    Version = long.Parse(parts[1]),
                    LastModified = DateTime.Parse(parts[2])
                };
                _cache[accountId] = balance;
                return balance;
            }
            finally
            {
                _rwLock.ExitReadLock();
            }
        }

        public bool UpdateBalance(string accountId, decimal newBalance, long expectedVersion)
        {
            // First, verify the version under read lock
            _rwLock.EnterReadLock();
            AccountBalance current;
            try
            {
                current = GetBalanceInternal(accountId);
                if (current != null && current.Version != expectedVersion)
                    return false;
            }
            finally
            {
                _rwLock.ExitReadLock();
            }

            // Now acquire write lock to perform the update
            _rwLock.EnterWriteLock();
            try
            {
                var updated = new AccountBalance
                {
                    AccountId = accountId,
                    Balance = newBalance,
                    Version = (current?.Version ?? 0) + 1,
                    LastModified = DateTime.UtcNow
                };

                var path = GetAccountPath(accountId);
                var content = $"{updated.Balance}|{updated.Version}|{updated.LastModified:O}";
                File.WriteAllText(path, content);
                _cache[accountId] = updated;
                return true;
            }
            finally
            {
                _rwLock.ExitWriteLock();
            }
        }

        private AccountBalance GetBalanceInternal(string accountId)
        {
            if (_cache.TryGetValue(accountId, out var cached))
                return cached;
            var path = GetAccountPath(accountId);
            if (!File.Exists(path))
                return null;
            var data = File.ReadAllText(path);
            var parts = data.Split('|');
            return new AccountBalance
            {
                AccountId = accountId,
                Balance = decimal.Parse(parts[0]),
                Version = long.Parse(parts[1]),
                LastModified = DateTime.Parse(parts[2])
            };
        }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class TransferController : ControllerBase
    {
        private readonly ILedgerStore _ledger;
        private readonly int _maxRetries = 3;

        public TransferController(ILedgerStore ledger)
        {
            _ledger = ledger;
        }

        [HttpPost("transfer")]
        public IActionResult Transfer([FromBody] TransferRequest request)
        {
            if (string.IsNullOrWhiteSpace(request?.FromAccount) ||
                string.IsNullOrWhiteSpace(request?.ToAccount))
                return BadRequest("Invalid accounts");

            if (request.Amount <= 0 || request.Amount > 1_000_000)
                return BadRequest("Invalid amount");

            if (request.FromAccount == request.ToAccount)
                return BadRequest("Cannot transfer to same account");

            for (int attempt = 0; attempt < _maxRetries; attempt++)
            {
                var fromBalance = _ledger.GetBalance(request.FromAccount);
                if (fromBalance == null)
                    return NotFound("Source account not found");

                if (fromBalance.Balance < request.Amount)
                    return BadRequest("Insufficient funds");

                var toBalance = _ledger.GetBalance(request.ToAccount);
                if (toBalance == null)
                    return NotFound("Destination account not found");

                // Debit source
                var debitSuccess = _ledger.UpdateBalance(
                    request.FromAccount,
                    fromBalance.Balance - request.Amount,
                    fromBalance.Version);

                if (!debitSuccess)
                    continue; // Retry on version conflict

                // Credit destination
                var creditSuccess = _ledger.UpdateBalance(
                    request.ToAccount,
                    toBalance.Balance + request.Amount,
                    toBalance.Version);

                if (!creditSuccess)
                {
                    // Rollback debit - but use stale version!
                    _ledger.UpdateBalance(
                        request.FromAccount,
                        fromBalance.Balance,
                        fromBalance.Version + 1);
                    continue;
                }

                return Ok(new { Message = "Transfer complete", TransactionVersion = fromBalance.Version + 1 });
            }

            return Conflict("Transfer failed after retries");
        }
    }

    public class TransferRequest
    {
        public string FromAccount { get; set; }
        public string ToAccount { get; set; }
        public decimal Amount { get; set; }
    }
}
